#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 2000) {
        return 0;
    }
    int values[2000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    long long inversions = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (values[i] > values[j]) {
                inversions++;
            }
        }
    }
    printf("%lld\n", inversions);
    return 0;
}

