int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }
    long long min_price;
    scanf("%lld", &min_price);
    long long best = 0;
    for (int j = 1; j < n; j++) {
        long long price;
        scanf("%lld", &price);
        if (price - min_price > best) {
            best = price - min_price;
        }
        if (price < min_price) {
            min_price = price;
        }
    }
    printf("%lld\n", best);
    return 0;
}

