#include <stdio.h>

int main(void) {
    int n, x;
    if (scanf("%d %d", &n, &x) != 2 || n < 0 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int write = 0;
    for (int read = 0; read < n; read++) {
        if (values[read] != x) {
            values[write] = values[read];
            write++;
        }
    }
    n = write;
    printf("%d\n", n);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d", values[i]);
    }
    printf("\n");
    return 0;
}

