#include <stdio.h>

#define MAX_VALUE 1000000

static int count[MAX_VALUE + 1];

int main(void) {
    int n;
    long long target;
    if (scanf("%d %lld", &n, &target) != 2) {
        return 0;
    }
    long long pairs = 0;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            break;
        }
        long long need = target - x;
        if (need >= 0 && need <= MAX_VALUE) {
            pairs += count[need];
        }
        count[x]++;
    }
    printf("%lld\n", pairs);
    return 0;
}

